slug: idempotent-consumer-marks-processed-too-early
stack: dotnet
topic: distributed
level: middle
type: find-bug
grading: auto
tags: [idempotency, idempotent-consumer, at-least-once, redelivery]
code:
  language: csharp
  harness: statements
  source: |
    var processed = new HashSet<string>();
    int balance = 0;
    int attempts = 0;

    void CreditAccount(int amount)
    {
        attempts++;
        if (attempts == 1)
            throw new TimeoutException("Database timeout");
        balance += amount;
    }

    void Handle(string messageId, int amount)
    {
        if (processed.Contains(messageId))
            return; // duplicate, already handled
        processed.Add(messageId);
        CreditAccount(amount);
    }

    // The broker redelivers the message until the handler succeeds.
    for (int delivery = 1; delivery <= 2; delivery++)
    {
        try
        {
            Handle("msg-42", 100);
            break;
        }
        catch (TimeoutException)
        {
            // No ack, so the broker delivers the message again.
        }
    }

    Console.WriteLine(balance);
bugLineSets: [[17], [17, 18]]
fixedSource: |
  var processed = new HashSet<string>();
  int balance = 0;
  int attempts = 0;

  void CreditAccount(int amount)
  {
      attempts++;
      if (attempts == 1)
          throw new TimeoutException("Database timeout");
      balance += amount;
  }

  void Handle(string messageId, int amount)
  {
      if (processed.Contains(messageId))
          return; // duplicate, already handled
      CreditAccount(amount);
      processed.Add(messageId); // mark only after the side effect succeeded
  }

  // The broker redelivers the message until the handler succeeds.
  for (int delivery = 1; delivery <= 2; delivery++)
  {
      try
      {
          Handle("msg-42", 100);
          break;
      }
      catch (TimeoutException)
      {
          // No ack, so the broker delivers the message again.
      }
  }

  Console.WriteLine(balance);
fixedExpect: { kind: output, value: "100" }
